class Solution {
public:
    int maximumProduct(vector<int>& nums, int k) {
        int n = nums.size();
        sort(nums.begin(), nums.end());
        long long sum = 0;
        int i = 0;
        for (; i < n; ++i) {
            sum += nums[i];
            long long needed = (long long)nums[i] * (i + 1) - sum;
            if (needed > k) {
                break;
            }
        }

        long long mod = 1000000007;
        long long ans = 1;

        if (i < n) {
            long long count = i;
            long long base = nums[i - 1];
            long long prev_sum = sum - nums[i];
            long long rem = k - (base * count - prev_sum);
            long long q = rem / count;
            long long r = rem % count;

            for (int j = 0; j < r; ++j) {
                ans = (ans * (base + q + 1)) % mod;
            }
            for (int j = 0; j < count - r; ++j) {
                ans = (ans * (base + q)) % mod;
            }
            for (int j = i; j < n; ++j) {
                ans = (ans * nums[j]) % mod;
            }
        } else {
            long long count = n;
            long long base = nums[n - 1];
            long long rem = k - (base * count - sum);
            long long q = rem / count;
            long long r = rem % count;

            for (int j = 0; j < r; ++j) {
                ans = (ans * (base + q + 1)) % mod;
            }
            for (int j = 0; j < count - r; ++j) {
                ans = (ans * (base + q)) % mod;
            }
        }

        return ans;
    }
};
